import{_ as a,o as n,a as p,b as l}from"./app.C41L12d5.js";const d=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"C API","link":"/api/SIMD-API/c_api/README"},{"text":"Memory矢量计算","link":"/api/SIMD-API/c_api/vector_compute/vector_compute"},{"text":"排序计算","link":"/api/SIMD-API/c_api/vector_compute/vector_sort/vector_sort"},{"text":"asc_get_vms4_sr","link":"/api/SIMD-API/c_api/vector_compute/vector_sort/asc_get_vms4_sr"}]},"headers":[],"relativePath":"api/SIMD-API/c_api/vector_compute/vector_sort/asc_get_vms4_sr.md","filePath":"api/SIMD-API/c_api/vector_compute/vector_sort/asc_get_vms4_sr.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"流水类型","slug":"流水类型","link":"#流水类型"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1788435672000}'),c={name:"api/SIMD-API/c_api/vector_compute/vector_sort/asc_get_vms4_sr.md"};function t(e,s,r,i,_,o){return n(),p("div",null,[...s[0]||(s[0]=[l(`<div><article class="markdown-body"><h1>asc_get_vms4_sr</h1><h2 id="产品支持情况">产品支持情况<a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：不支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><p>头文件路径为：<code>&quot;c_api/vector_compute/compute/vector_sort.h&quot;</code>。</p><p>此接口用于获取执行<a href="asc_mrgsort4.html">asc_mrgsort4</a>操作后的4个队列中，每个队列已经理过的Region Proposal个数。使用时，需要将asc_mrgsort4中的if_exhausted_suspension参数配置为true，该配置模式下某条队列耗尽后，MrgSort4指令停止。</p><h2 id="函数原型">函数原型<a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">asc_get_vms4_sr</span><span class="p">(</span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">sorted_num</span><span class="p">[</span><span class="n">ASC_C_API_MRGSORT_ELEMENT_LEN</span><span class="p">])</span>
</code></pre></div><h2 id="参数说明">参数说明<a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 参数说明</p><table><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>sorted_num</td><td>输出</td><td>每个队列已经理过的Region Proposal个数。队列数量ASC_C_API_MRGSORT_ELEMENT_LEN值为4。</td></tr></tbody></table><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="流水类型">流水类型<a class="header-anchor" href="#流水类型">​</a></h2><p>PIPE_S</p><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><ul><li>需和<a href="asc_mrgsort4.html">asc_mrgsort4</a>操作配合使用，且需asc_mrgsort4中的if_exhausted_suspension参数配置为true。</li><li>需通过同步操作确保<a href="asc_mrgsort4.html">asc_mrgsort4</a>执行完成后再调用本接口获取结果。</li></ul><h2 id="调用示例">调用示例<a class="header-anchor" href="#调用示例">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// 示例对4个已排序好的Region Proposal队列进行归并排序，每个队列包含32个元素。</span>
<span class="k">constexpr</span><span class="w"> </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">element_length</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">32</span><span class="p">;</span>
<span class="k">constexpr</span><span class="w"> </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">array_length</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">element_length</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="mi">2</span><span class="p">;</span>
<span class="c1">// 每个元素包含float32的score和4字节的index，占8字节，相当于2个sizeof(float)。</span>
<span class="n">__ubuf__</span><span class="w"> </span><span class="kt">float</span><span class="w"> </span><span class="n">src_workspace</span><span class="p">[</span><span class="n">array_length</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="mi">4</span><span class="p">];</span>

<span class="n">__ubuf__</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">src</span><span class="p">[</span><span class="n">ASC_C_API_MRGSORT_ELEMENT_LEN</span><span class="p">];</span>
<span class="n">__ubuf__</span><span class="w"> </span><span class="kt">float</span><span class="w"> </span><span class="n">dst</span><span class="p">[</span><span class="n">array_length</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="mi">4</span><span class="p">];</span>

<span class="kt">uint8_t</span><span class="w"> </span><span class="n">repeat</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">1</span><span class="p">;</span>
<span class="kt">uint8_t</span><span class="w"> </span><span class="n">valid_bit</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mb">0b1111</span><span class="p">;</span>
<span class="kt">bool</span><span class="w"> </span><span class="n">if_exhausted_suspension</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="nb">true</span><span class="p">;</span>
<span class="n">src</span><span class="p">[</span><span class="mi">0</span><span class="p">]</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="o">&amp;</span><span class="n">src_workspace</span><span class="p">[</span><span class="mi">0</span><span class="p">];</span>
<span class="n">src</span><span class="p">[</span><span class="mi">1</span><span class="p">]</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="o">&amp;</span><span class="n">src_workspace</span><span class="p">[</span><span class="mi">1</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">array_length</span><span class="p">];</span>
<span class="n">src</span><span class="p">[</span><span class="mi">2</span><span class="p">]</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="o">&amp;</span><span class="n">src_workspace</span><span class="p">[</span><span class="mi">2</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">array_length</span><span class="p">];</span>
<span class="n">src</span><span class="p">[</span><span class="mi">3</span><span class="p">]</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="o">&amp;</span><span class="n">src_workspace</span><span class="p">[</span><span class="mi">3</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">array_length</span><span class="p">];</span>

<span class="n">asc_mrgsort4</span><span class="p">(</span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="n">src</span><span class="p">,</span><span class="w"> </span><span class="n">repeat</span><span class="p">,</span><span class="w"> </span><span class="n">element_length</span><span class="p">,</span><span class="w"> </span><span class="n">element_length</span><span class="p">,</span><span class="w"> </span><span class="n">element_length</span><span class="p">,</span><span class="w"> </span><span class="n">element_length</span><span class="p">,</span><span class="w"> </span><span class="n">if_exhausted_suspension</span><span class="p">,</span><span class="w"> </span><span class="n">valid_bit</span><span class="p">);</span>
<span class="n">asc_sync</span><span class="p">();</span>

<span class="kt">uint16_t</span><span class="w"> </span><span class="n">sorted_num</span><span class="p">[</span><span class="n">ASC_C_API_MRGSORT_ELEMENT_LEN</span><span class="p">];</span>
<span class="n">asc_get_vms4_sr</span><span class="p">(</span><span class="n">sorted_num</span><span class="p">);</span>
</code></pre></div></article></div>`,1)])])}const v=a(c,[["render",t]]);export{d as __pageData,v as default};
